def _load_legacy_modules() -> dict[str, types.ModuleType]:
    loaded: dict[str, types.ModuleType] = {}
    package = __package__ or "examples_merak.aigc.lingbot_video"
    for key in _LOAD_ORDER:
        module_name = _LEGACY_MODULE_NAMES[key]
        module = types.ModuleType(module_name)
        module.__file__ = __file__
        module.__package__ = package
        sys.modules[module_name] = module
        exec(compile(_LEGACY_SOURCES[key], __file__, "exec"), module.__dict__)
        loaded[key] = module
    return loaded


_LEGACY_MODULES = _load_legacy_modules()

# Re-export helpers used by neighboring LingBot debug utilities.
DEFAULT_HEIGHT = _LEGACY_MODULES["components"].DEFAULT_HEIGHT
DEFAULT_MODEL_DIR = _LEGACY_MODULES["components"].DEFAULT_MODEL_DIR
DEFAULT_PROMPT_JSON = _LEGACY_MODULES["components"].DEFAULT_PROMPT_JSON
DEFAULT_WIDTH = _LEGACY_MODULES["components"].DEFAULT_WIDTH
_WrappedTransformerPipelineAdapter = _LEGACY_MODULES["components"]._WrappedTransformerPipelineAdapter
_clear_cuda = _LEGACY_MODULES["components"]._clear_cuda
_load_float_components = _LEGACY_MODULES["components"]._load_float_components
_load_frontend_graph_transformer = _LEGACY_MODULES["components"]._load_frontend_graph_transformer
_load_hmonnx_transformer = _LEGACY_MODULES["components"]._load_hmonnx_transformer
_load_prompt = _LEGACY_MODULES["components"]._load_prompt
_new_pipe_like = _LEGACY_MODULES["components"]._new_pipe_like
_run_trace = _LEGACY_MODULES["denoise_steps_front_hmonnx"]._run_trace
