SingleBlockExportWrapper = _LEGACY_MODULES["hmonnx_vs_front_blocks"].SingleBlockExportWrapper
_initial_block_state = _LEGACY_MODULES["hmonnx_vs_front_blocks"]._initial_block_state
_load_component_cfg = _LEGACY_MODULES["hmonnx_vs_front_blocks"]._load_component_cfg
_load_meta = _LEGACY_MODULES["hmonnx_vs_front_blocks"]._load_meta
_prepare_full_inputs = _LEGACY_MODULES["hmonnx_vs_front_blocks"]._prepare_full_inputs
_torch_dtype = _LEGACY_MODULES["hmonnx_vs_front_blocks"]._torch_dtype
_prepare_model = _LEGACY_MODULES["front_router_blocks"]._prepare_model


def available_modes() -> tuple[str, ...]:
    return tuple(_MODES)


def run_mode(mode: str, argv: list[str] | None = None) -> Any:
    if mode not in _MODES:
        raise ValueError(f"unknown mode {mode!r}; expected one of {', '.join(available_modes())}")
    module = _LEGACY_MODULES[_MODES[mode]]
    old_argv = sys.argv[:]
    try:
        sys.argv = [f"{old_argv[0]} --mode {mode}", *(argv or [])]
        return module.main()
    finally:
        sys.argv = old_argv


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Run one LingBot compare mode from the unified compare script.",
        formatter_class=argparse.ArgumentDefaultsHelpFormatter,
    )
    parser.add_argument("--mode", choices=available_modes(), default="front-autocast-blocks")
    args, mode_args = parser.parse_known_args()
    args.mode_args = mode_args
    return args


def main() -> Any:
    args = parse_args()
    return run_mode(args.mode, args.mode_args)


if __name__ == "__main__":
    main()
